<template><div class="cpw-overlay" @click.self="$emit('close')"><div class="cpw-modal"><button class="cpw-close" @click="$emit('close')">&times;</button><h2>{{t('changePasswordTitle')}}</h2><form class="cpw-form" @submit.prevent="submit"><div class="cpw-field"><label>{{t('oldPassword')}}</label><input v-model="oldPassword" type="password" :placeholder="t('oldPasswordPlaceholder')" required></div><div class="cpw-field"><label>{{t('newPassword')}}</label><input v-model="newPassword" type="password" :placeholder="t('newPasswordPlaceholder')" required></div><div class="cpw-field"><label>{{t('confirmNewPassword')}}</label><input v-model="confirm" type="password" :placeholder="t('confirmPasswordPlaceholder')" required></div><div v-if="error" class="cpw-error">{{error}}</div><div v-if="success" class="cpw-success">{{success}}</div><button class="cpw-submit" :disabled="loading">{{loading?t('submitting'):t('confirmChange')}}</button></form></div></div></template><script setup>import {ref} from 'vue';import {useLang} from '../contexts/app';import api from '../services/api';import './ChangePasswordModal.css';const emit=defineEmits(['close']);const {t}=useLang();const oldPassword=ref(''),newPassword=ref(''),confirm=ref(''),error=ref(''),success=ref(''),loading=ref(false);const submit=async()=>{error.value='';if(newPassword.value.length<4){error.value=t('passwordMinLength');return}if(newPassword.value!==confirm.value){error.value=t('passwordMismatch');return}loading.value=true;try{await api.put('/auth/change-password',{old_password:oldPassword.value,new_password:newPassword.value});success.value=t('passwordChanged');setTimeout(()=>emit('close'),1500)}catch(e){error.value=e.response?.data?.detail||t('changeFailed')}finally{loading.value=false}};</script>
